WITH first_login AS (
    SELECT player_id, MIN(event_date) AS first_day FROM Activity GROUP BY player_id
)

SELECT s.product_id, s.year AS first_year, s.quantity, s.price
FROM Sales s JOIN (SELECT product_id, MIN(year) AS first_year FROM Sales GROUP BY product_id) f
ON s.product_id = f.product_id AND s.year = f.first_year;

SELECT MAX(num) AS num FROM (
    SELECT num FROM MyNumbers GROUP BY num HAVING COUNT(*) = 1
) singles;

GROUP BY c.customer_id
HAVING (SELECT COUNT(*) FROM Product) = COUNT(DISTINCT CASE
    WHEN c.product_key IN (SELECT product_key FROM Product) THEN c.product_key END);

WITH counted AS (
    SELECT *, COUNT(*) OVER (PARTITION BY employee_id) AS n_departments FROM Employee
)

WHERE e.salary < 30000 AND e.manager_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM Employees m WHERE m.employee_id = e.manager_id)
ORDER BY e.employee_id;

